// ❌ OLD WAY: 50 lines of Thunks, Reducers, and useEffects.

// ✅ NEW WAY (RTK Query in a Component):
import { useGetPokemonByNameQuery } from './pokemonApi'

export const PokemonView = ({ name }) => {
  // That's it. One line of code handles the fetch, the cache, and the loading state!
  const { data, error, isLoading } = useGetPokemonByNameQuery(name)

  if (isLoading) return <div>Loading...</div>
  if (error) return <div>Error!</div>
  return <div>{data.sprites.front_default}</div>
}
